export type Coverage = {
  status: Status
  gaps?: string[]
}

export const Status = {
  UNKNOWN: 'unknown',
  NONE: 'not_covered',
  PARTIAL: 'partially_covered',
  FULL: 'fully_covered',
} as const
export type Status = (typeof Status)[keyof typeof Status]

export const StatusMap: Record<
  Status,
  {
    iconEl?: string // keyof BranchProtectionRowElement
    label?: string
  }
> = {
  [Status.UNKNOWN]: {},
  [Status.NONE]: {
    iconEl: 'noCoverageIcon',
    label: 'No coverage',
  },
  [Status.PARTIAL]: {
    iconEl: 'partialCoverageIcon',
    label: 'Partial coverage',
  },
  [Status.FULL]: {
    iconEl: 'fullCoverageIcon',
    label: 'Full coverage',
  },
}

export type ErrorResponse = {
  error: string
  coverage?: Coverage
}
