import {attr, controller, target} from '@github/catalyst'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {type Coverage, type ErrorResponse, Status, StatusMap} from './types'

declare module 'react' {
  namespace JSX {
    interface IntrinsicElements {
      'branch-protection-row': CustomElement<typeof BranchProtectionRowElement>
    }
  }
}

@controller('branch-protection-row')
export class BranchProtectionRowElement extends HTMLElement {
  @target declare fullCoverageIcon: HTMLElement
  @target declare partialCoverageIcon: HTMLElement
  @target declare noCoverageIcon: HTMLElement
  @target declare errorIcon: HTMLElement
  @target declare messageText: HTMLElement
  @target declare loadingIcon: HTMLElement

  @attr migrateUrl = ''
  @attr coverageUrl = ''

  async migrate() {
    if (!isFeatureEnabled('branch_protection_migration_assistant')) return

    this.#showLoading()
    const response = await verifiedFetchJSON(this.migrateUrl, {
      method: 'POST',
    })
    if (response.ok) {
      const {coverage} = (await response.json()) as {
        rulesets: unknown[]
        coverage: Coverage
      }
      this.#setCoverage(coverage)
    } else {
      try {
        const {coverage, error} = (await response.json()) as ErrorResponse
        this.#showError(error, coverage)
        // eslint-disable-next-line unused-imports/no-unused-vars
      } catch (error) {
        this.#showError()
      }
    }
  }

  async connectedCallback() {
    if (!this.coverageUrl) return
    if (!isFeatureEnabled('branch_protection_migration_assistant')) return

    const response = await verifiedFetchJSON(this.coverageUrl)
    if (response.ok) {
      const coverage = (await response.json()) as Coverage
      this.#setCoverage(coverage)
    }
  }

  // private

  #setCoverage({status, gaps}: Coverage) {
    this.#hideElement(this.errorIcon)
    this.#hideElement(this.loadingIcon)
    this.#hideElement(this.messageText)
    for (const statusKey of Object.values(Status)) {
      const elKey = StatusMap[statusKey].iconEl
      const el = elKey ? (this[elKey as keyof this] as HTMLElement) : undefined
      if (el && statusKey !== status) {
        this.#hideElement(el)
      }
    }
    const {iconEl, label} = StatusMap[status]
    if (iconEl) {
      const icon = this[iconEl as keyof this] as HTMLElement
      this.#showElement(icon)
    }

    if (gaps?.length) {
      this.messageText.textContent = gaps.length === 1 ? (gaps[0] as string) : 'Multiple differences'
    } else if (label) {
      this.messageText.textContent = label
    }

    if (gaps?.length || label) {
      this.messageText.classList.remove('fgColor-danger')
      this.messageText.classList.add('fgColor-muted')
      this.#showElement(this.messageText)
    }
  }

  #showLoading() {
    this.#setCoverage({status: Status.UNKNOWN})
    this.#showElement(this.loadingIcon)
  }

  #showError(message?: string, coverage?: Coverage) {
    this.#setCoverage(coverage ?? {status: Status.UNKNOWN})
    this.messageText.textContent = message || 'An error occurred'
    this.messageText.classList.remove('fgColor-muted')
    this.messageText.classList.add('fgColor-danger')
    this.#showElement(this.messageText)
    if (!coverage) {
      this.#showElement(this.errorIcon)
    }
  }

  #showElement(element: HTMLElement) {
    element.removeAttribute('hidden')
  }

  #hideElement(element: HTMLElement) {
    element.setAttribute('hidden', 'true')
  }
}
